(function(){
'use strict';
if(window.__SP_L8T2_VOCAB_PRACTICE_UI_20260901)return;
window.__SP_L8T2_VOCAB_PRACTICE_UI_20260901=true;
const base=window.L8UI;if(!base||typeof base.taskPage!=='function')return;
const originalTaskPage=base.taskPage,S=()=>window.L8S,T=()=>window.L8_THEME;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const imageSrc=raw=>{const v=String(raw||'').trim();if(!v)return'';return /^https?:\/\//i.test(v)?v:`https://sprachpilot.b-cdn.net/${v.replace(/^\/+/, '')}`};
function currentTask(){const id=new URLSearchParams(location.search).get('task');return (T()?.tasks||[]).find(t=>String(t?.id)===String(id))}
function taskNumber(task){const i=(T()?.tasks||[]).findIndex(x=>x.id===task.id);return i>=0?i+1:''}
function previewNote(){return S()?.preview?.()?'<div class="sp-teacher-preview-note">Lehrer-Vorschau: Es werden keine Teilnehmerpunkte und keine Teilnehmerfortschritte gespeichert.</div>':''}
function taskHead(task,state){const total=Math.max(1,task.items.length),done=state.done?.length||0,pct=Math.round(done/total*100),emoji=task.emoji||task.icon||'✅';return `<section class="l8-card l8-task-head"><div class="l8-task-title-block"><span class="l8-task-kicker">Aufgabe ${taskNumber(task)}</span><h1>${esc(task.title)}</h1><p>${esc(emoji)} ${esc(task.instruction||'')}</p></div><div class="l8-progress-row"><span>${done} von ${task.items.length} fertig</span><strong>${pct}%</strong></div><div class="l8-progress"><div style="width:${pct}%"></div></div></section>`}
function feedback(type,text){const box=document.getElementById('feedback');if(box)box.innerHTML=`<div class="l8-feedback ${type}">${esc(text)}</div>`}
function hashSeed(text){let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function stableShuffle(values,seedText){const a=[...(values||[])];let seed=hashSeed(seedText)||1;for(let i=a.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function finish(task,root){root.innerHTML=`<div class="l8-wrap">${previewNote()}<section class="l8-card l8-finish"><div class="l8-finish-icon">✓</div><h2>Aufgabe abgeschlossen</h2><p>Du hast die Aufgabe zu 100 % abgeschlossen.</p><div class="l8-row l8-center-actions"><a class="l8-btn primary" href="index.html">Zur Themenübersicht</a></div></section></div>`}
function renderListening(task,root){let state=S().load(T().number,task.id,task.items.length),idx=S().nextIndex(T().number,task.id,task.items.length);if(idx==null||idx<0)return finish(task,root);state=S().load(T().number,task.id,task.items.length);const item=task.items[idx],options=stableShuffle(item.options||[],`${T().number}|${task.id}|${idx}|${S().pid?.()||''}`);root.innerHTML=`<div class="l8-wrap">${previewNote()}${taskHead(task,state)}<section class="l8-card l8-exercise l8-vocab-listen"><div class="l8-vocab-listen-top"><button class="l8-btn l8-audio" id="vocabListen" type="button">🔊 Wort anhören</button></div><div class="l8-image-choice-grid">${options.map((o,i)=>`<button class="l8-image-choice" type="button" data-term="${esc(o.term)}" aria-label="Bild ${i+1}"><img src="${esc(imageSrc(o.image))}" alt="" loading="lazy"></button>`).join('')}</div><div id="feedback"></div></section></div>`;document.getElementById('vocabListen').onclick=()=>S().say(item.term,item.audioFile||item.audio);root.querySelectorAll('.l8-image-choice').forEach(btn=>btn.onclick=()=>{const answer=btn.dataset.term||'';if(S().equal(answer,item.answer)){btn.classList.add('correct');const r=S().right(T().number,task.id,task.items.length,idx,answer);feedback('good',r.needsReview?'Richtig. Dieses Wort kommt am Ende noch einmal.':'Richtig!');setTimeout(()=>renderListening(task,root),550)}else{btn.classList.add('wrong');const r=S().wrong(T().number,task.id,task.items.length,idx,answer);feedback(r.tries===1?'bad':'warn',r.tries===1?'Noch nicht richtig. Hör noch einmal.':'Hör das Wort noch einmal und achte auf das Bild.')}})}
function migrateOldMemory(task){let state=S().load(T().number,task.id,task.items.length);if((state.done||[]).length>1)return state;try{const old=JSON.parse(String(state.answers?.[0]||''));if(Array.isArray(old)&&old.length){for(const raw of old){const i=Number(raw);if(Number.isInteger(i)&&i>=0&&i<task.items.length&&!state.done.includes(i)){let r=S().right(T().number,task.id,task.items.length,i,'memory-pair');if(r.needsReview)r=S().right(T().number,task.id,task.items.length,i,'memory-pair');state=r.s}}}}catch(e){}return S().load(T().number,task.id,task.items.length)}
function renderMemory(task,root){let state=migrateOldMemory(task);const pairs=(task.items||[]).map((p,i)=>({...p,_id:String(i),_index:i})).filter(p=>p.term&&p.image),matched=new Set((state.done||[]).map(String));if(pairs.length&&matched.size>=pairs.length)return finish(task,root);const cards=[];pairs.forEach(p=>{cards.push({pair:p._id,side:'word',text:p.term});cards.push({pair:p._id,side:'image',image:p.image,term:p.term})});const board=stableShuffle(cards,`${T().number}|${task.id}|memory|${S().pid?.()||''}`);root.innerHTML=`<div class="l8-wrap">${previewNote()}${taskHead(task,state)}<section class="l8-card l8-exercise l8-memory-exercise"><div class="l8-memory-status"><strong>${matched.size} von ${pairs.length} Paaren gefunden</strong></div><div class="l8-memory-grid">${board.map((c,i)=>`<button class="l8-memory-card ${matched.has(c.pair)?'matched revealed':''}" type="button" data-pair="${esc(c.pair)}" data-side="${esc(c.side)}" data-card="${i}" ${matched.has(c.pair)?'disabled':''}><span class="l8-memory-front">?</span><span class="l8-memory-back">${c.side==='image'?`<img src="${esc(imageSrc(c.image))}" alt="" loading="lazy">`:`<strong>${esc(c.text)}</strong>`}</span></button>`).join('')}</div><div id="feedback"></div></section></div>`;let open=[];const refreshProgress=()=>{state=S().load(T().number,task.id,task.items.length);const done=state.done?.length||0,pct=Math.round(done/Math.max(1,task.items.length)*100);const status=root.querySelector('.l8-memory-status strong');if(status)status.textContent=`${done} von ${pairs.length} Paaren gefunden`;const row=root.querySelector('.l8-progress-row');if(row)row.innerHTML=`<span>${done} von ${task.items.length} fertig</span><strong>${pct}%</strong>`;const bar=root.querySelector('.l8-task-head .l8-progress > div');if(bar)bar.style.width=`${pct}%`;return done};root.querySelectorAll('.l8-memory-card:not(.matched)').forEach(card=>card.onclick=()=>{if(card.classList.contains('revealed')||card.classList.contains('matched')||card.classList.contains('checking'))return;card.classList.add('revealed');open.push(card);if(open.length<2)return;const [a,b]=open;open=[];const same=a.dataset.pair===b.dataset.pair&&a.dataset.side!==b.dataset.side;if(same){const pairIndex=Number(a.dataset.pair);a.classList.add('checking');b.classList.add('checking');let r=S().right(T().number,task.id,task.items.length,pairIndex,task.items[pairIndex]?.term||'memory-pair');if(r.needsReview)r=S().right(T().number,task.id,task.items.length,pairIndex,task.items[pairIndex]?.term||'memory-pair');matched.add(a.dataset.pair);a.classList.add('matched');b.classList.add('matched');a.disabled=true;b.disabled=true;a.classList.remove('checking');b.classList.remove('checking');const done=refreshProgress();feedback('good','Paar gefunden!');if(done>=pairs.length)setTimeout(()=>finish(task,root),450);return}a.classList.add('checking');b.classList.add('checking');feedback('warn','Das passt noch nicht zusammen.');setTimeout(()=>{for(const node of[a,b]){if(node.isConnected)node.classList.remove('revealed','checking')}},500)})}
function patchedTaskPage(){const task=currentTask(),root=document.getElementById('app');if(!task||!root)return originalTaskPage();if(task.kind==='vocab-listen-image')return renderListening(task,root);if(task.kind==='vocab-memory')return renderMemory(task,root);return originalTaskPage()}
window.L8UI={...base,taskPage:patchedTaskPage};
const style=document.createElement('style');style.id='sp-l8t2-vocab-practice-ui';style.textContent=`.l8-vocab-listen{max-width:900px;margin-inline:auto}.l8-vocab-listen-top{display:flex;justify-content:center;margin-bottom:18px}.l8-image-choice-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.l8-image-choice{min-height:190px;border:2px solid var(--lesson-line,var(--l8-line));border-radius:18px;background:#fff;padding:10px;cursor:pointer}.l8-image-choice img{width:100%;height:180px;object-fit:contain;border-radius:12px}.l8-image-choice.correct{outline:4px solid rgba(39,155,91,.25)}.l8-image-choice.wrong{opacity:.58}.l8-memory-exercise{max-width:1100px;margin-inline:auto}.l8-memory-status{text-align:center;margin-bottom:14px;color:var(--lesson-main-dark,var(--l8-dark))}.l8-memory-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}.l8-memory-card{position:relative;min-height:112px;border:2px solid var(--lesson-line,var(--l8-line));border-radius:15px;background:var(--lesson-main,var(--l8-main));color:#fff;padding:8px;cursor:pointer;overflow:hidden}.l8-memory-front,.l8-memory-back{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:8px;box-sizing:border-box}.l8-memory-front{font-size:30px;font-weight:900}.l8-memory-back{opacity:0;background:#fff;color:var(--lesson-text,#20384a);text-align:center}.l8-memory-back strong{font-size:14px;line-height:1.25;overflow-wrap:anywhere}.l8-memory-back img{width:100%;height:100%;object-fit:contain;border-radius:9px}.l8-memory-card.revealed .l8-memory-front{opacity:0}.l8-memory-card.revealed .l8-memory-back{opacity:1}.l8-memory-card.matched{border-color:var(--lesson-main-dark,var(--l8-dark));box-shadow:0 0 0 3px rgba(64,140,188,.12)}.l8-memory-card.checking{pointer-events:none}@media(max-width:760px){.l8-memory-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:620px){.l8-image-choice-grid{gap:9px}.l8-image-choice{min-height:145px;padding:7px}.l8-image-choice img{height:135px}.l8-memory-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.l8-memory-card{min-height:96px;padding:5px}.l8-memory-back strong{font-size:12px}}`;
document.head.appendChild(style);
})();